query.text:

declare @key2 nvarchar(3000)
SELECT @key2 = (CASE WHEN @lookupKey = '' THEN '1=1' ELSE @lookupKey END) + CASE WHEN @val = '' THEN ''ELSE ' AND (@@fieldKey LIKE N''%' + dbo.ISWIFTFunctionReplaceSQLValue(@val) + '%''' + ' OR @@fieldName LIKE N''%' + dbo.ISWIFTFunctionReplaceSQLValue(@val) + '%'')' END;
exec ISWIFTStoreTableLoading '@@table', '@@fieldKey', '@@fields', @@fieldOrder, '', '', 'left join dmkhupho d on a.ma_khupho = d.ma_khupho and a.ma_phuongxa = d.ma_phuongxa left join dmphuongxa e on a.ma_phuongxa = e.ma_phuongxa left join dmttp f on a.ma_ttp = f.ma_ttp', 'd.ten_khupho, e.ten_phuongxa, f.ten_ttp', N'@@key', @key2, @@filterKey, '', @pageIndex, 10, @@admin, @@userId
